// PATCH contract: ProfileService.patch
const isInvalid = (fn) => assert.throws(fn, (err) => err instanceof Error && err.message === 'invalid profile');
const fresh = () => new ProfileService({ displayName: 'before', tags: ['old'] });
const snapshot = (s) => JSON.stringify(s.profile);

// Absent fields retain stored values; empty object is a no-op.
{
  const s = new ProfileService({ displayName: 'keep', tags: ['a', 'b'] });
  assert.deepEqual(s.patch({}), { displayName: 'keep', tags: ['a', 'b'] });
  const n = new ProfileService({ displayName: null, tags: [] });
  assert.deepEqual(n.patch({ tags: ['x'] }), { displayName: null, tags: ['x'] });
  assert.deepEqual(n.patch(Object.create(null)), { displayName: null, tags: ['x'] });
}

// displayName: null clears; strings are trimmed; length 1..40 after trim.
{
  assert.equal(fresh().patch({ displayName: null }).displayName, null);
  assert.equal(fresh().patch({ displayName: '  Ada  ' }).displayName, 'Ada');
  assert.equal(fresh().patch({ displayName: 'x'.repeat(40) }).displayName, 'x'.repeat(40));
  assert.equal(fresh().patch({ displayName: '  ' + 'x'.repeat(40) + '  ' }).displayName, 'x'.repeat(40));
  isInvalid(() => fresh().patch({ displayName: '' }));
  isInvalid(() => fresh().patch({ displayName: '   ' }));
  isInvalid(() => fresh().patch({ displayName: 'x'.repeat(41) }));
  isInvalid(() => fresh().patch({ displayName: ' ' + 'x'.repeat(41) }));
  for (const bad of [0, 1, true, false, undefined, [], ['a'], {}]) {
    isInvalid(() => fresh().patch({ displayName: bad }));
  }
}

// tags: null or [] clears; array of <=5 distinct, trimmed, nonempty, <=12 chars.
{
  assert.deepEqual(fresh().patch({ tags: null }).tags, []);
  assert.deepEqual(fresh().patch({ tags: [] }).tags, []);
  assert.deepEqual(fresh().patch({ tags: [' a ', 'b'] }).tags, ['a', 'b']);
  assert.deepEqual(fresh().patch({ tags: ['1', '2', '3', '4', '5'] }).tags, ['1', '2', '3', '4', '5']);
  assert.deepEqual(fresh().patch({ tags: [' ' + 'x'.repeat(12) + ' '] }).tags, ['x'.repeat(12)]);
  isInvalid(() => fresh().patch({ tags: ['a', ' a '] }));
  isInvalid(() => fresh().patch({ tags: ['  '] }));
  isInvalid(() => fresh().patch({ tags: [''] }));
  isInvalid(() => fresh().patch({ tags: ['1', '2', '3', '4', '5', '6'] }));
  isInvalid(() => fresh().patch({ tags: ['x'.repeat(13)] }));
  isInvalid(() => fresh().patch({ tags: [' ' + 'x'.repeat(13)] }));
  isInvalid(() => fresh().patch({ tags: [1] }));
  isInvalid(() => fresh().patch({ tags: [null] }));
  isInvalid(() => fresh().patch({ tags: 'a' }));
  isInvalid(() => fresh().patch({ tags: 0 }));
  isInvalid(() => fresh().patch({ tags: {} }));
  const holey = ['a']; holey[2] = 'c';
  isInvalid(() => fresh().patch({ tags: holey }));
  isInvalid(() => fresh().patch({ tags: new Array(2) }));
}

// Unknown keys, bad top-level shapes and undefined values are rejected.
{
  isInvalid(() => fresh().patch({ displayName: 'ok', extra: 1 }));
  isInvalid(() => fresh().patch({ [Symbol('s')]: 1 }));
  isInvalid(() => fresh().patch({ tags: undefined }));
  isInvalid(() => fresh().patch({ displayName: undefined }));
  isInvalid(() => fresh().patch([]));
  isInvalid(() => fresh().patch(['displayName']));
  isInvalid(() => fresh().patch(null));
  isInvalid(() => fresh().patch(undefined));
  isInvalid(() => fresh().patch('displayName'));
  isInvalid(() => fresh().patch(42));
  class Custom { constructor() { this.displayName = 'x'; } }
  isInvalid(() => fresh().patch(new Custom()));
  isInvalid(() => fresh().patch(Object.create({ displayName: 'inherited' })));
  isInvalid(() => fresh().patch({ get displayName() { return 'x'; } }));
  isInvalid(() => fresh().patch({ get tags() { return []; } }));
}

// Invalid input leaves storage unchanged (all-or-nothing).
{
  const s = fresh();
  const before = snapshot(s);
  isInvalid(() => s.patch({ displayName: 'new', tags: ['a', 'a'] }));
  isInvalid(() => s.patch({ displayName: 'new', tags: ['a'], extra: true }));
  assert.equal(snapshot(s), before);
}

// Input is not mutated and the caller's tags array is never stored.
{
  const s = fresh();
  const tags = [' a ', 'b'];
  const input = { displayName: ' Ada ', tags };
  const result = s.patch(input);
  assert.deepEqual(input, { displayName: ' Ada ', tags: [' a ', 'b'] });
  assert.notEqual(s.profile.tags, tags);
  assert.notEqual(result.tags, tags);
  tags.push('c');
  assert.deepEqual(s.profile.tags, ['a', 'b']);
}

